// Share pending work before considering force or cache freshness.
if (this.inFlight) {
  return this.inFlight;
}
if (force !== true && this.lastUpdated !== null && Date.now() - this.lastUpdated < this.cacheTtlMs) {
  return this.$q.when(this.countries);
}
const generation = this.cacheGeneration;
this.loading = true;
this.error = null;
const query = 'query CountryDirectory { countries { code name native emoji capital currency phone continent { code name } languages { code name } } }';
this.inFlight = this.$q.when(null).then(() => {
  if (generation !== this.cacheGeneration) {
    throw new Error('Country cache was cleared.');
  }
  return this.$http.post('https://countries.trevorblades.com/', { query: query });
}).then((response) => {
  if (generation !== this.cacheGeneration) {
    throw new Error('Country cache was cleared.');
  }
  // HTTP success is not GraphQL success: reject errors before reading data.
  const envelope = response && response.data;
  if (!envelope || (envelope.errors && (!Array.isArray(envelope.errors) || envelope.errors.length > 0)) || !envelope.data || !Array.isArray(envelope.data.countries)) {
    throw new Error('Invalid country response.');
  }
  const records = envelope.data.countries.map((country) => {
    if (!country || typeof country.code !== 'string' || typeof country.name !== 'string' || !country.continent || typeof country.continent.code !== 'string' || typeof country.continent.name !== 'string' || !Array.isArray(country.languages)) {
      throw new Error('Invalid country record.');
    }
    return {
      code: country.code,
      name: country.name,
      native: country.native,
      emoji: country.emoji,
      capital: country.capital && country.capital.trim() ? country.capital : 'Not listed',
      currency: country.currency && country.currency.trim() ? country.currency : 'Not listed',
      phone: country.phone,
      continentCode: country.continent.code,
      continentName: country.continent.name,
      languages: country.languages.map((language) => {
        if (!language || typeof language.name !== 'string') {
          throw new Error('Invalid language record.');
        }
        return language.name;
      })
    };
  }).sort((a, b) => a.name.localeCompare(b.name));
  const continentMap = new Map();
  records.forEach((country) => {
    continentMap.set(country.continentCode, { code: country.continentCode, name: country.continentName });
  });
  const continents = Array.from(continentMap.values()).sort((a, b) => a.name.localeCompare(b.name));
  // Commit only complete, successfully normalized results.
  this.countries = records;
  this.continents = continents;
  this.lastUpdated = Date.now();
  return this.countries;
}).catch(() => {
  if (generation !== this.cacheGeneration) {
    throw new Error('Country cache was cleared. Please load again.');
  }
  this.error = 'Unable to load country data. Please try again.';
  throw new Error(this.error);
}).finally(() => {
  // An older invalidated request must not reset a newer request's flags.
  if (generation === this.cacheGeneration) {
    this.loading = false;
    this.inFlight = null;
  }
});
return this.inFlight;

const normalizedCode = String(code == null ? '' : code).trim().toUpperCase();
return this.loadCountries(false).then((countries) => {
  const country = countries.find((item) => item.code === normalizedCode);
  if (!country) {
    throw new Error('Country not found.');
  }
  return country;
});

this.cacheGeneration = this.cacheGeneration + 1;
this.inFlight = null;
this.countries = [];
this.continents = [];
this.lastUpdated = null;
this.error = null;
this.loading = false;
